package com.app.entity;
import jakarta.persistence.*; import lombok.*; import java.time.LocalDateTime;
@Entity @Table(name="society_daily_checklist_templates") @Data @Builder @NoArgsConstructor @AllArgsConstructor
public class SocietyDailyChecklistTemplate {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="account_id",nullable=false) private Account account; @Column(nullable=false,length=180) private String title; @Column(length=1000) private String description; @Column(nullable=false) @Builder.Default private Integer sortOrder=0; @Column(nullable=false) @Builder.Default private Boolean active=true; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="created_by_user_id",nullable=false) private User createdBy; @Column(nullable=false,updatable=false) @Builder.Default private LocalDateTime createdAt=LocalDateTime.now(); @Column(nullable=false) @Builder.Default private LocalDateTime updatedAt=LocalDateTime.now(); @PreUpdate void touch(){updatedAt=LocalDateTime.now();}}
